import React, { useState } from 'react';
import type { FlattenSimpleInterpolation } from 'styled-components';
import { css, keyframes } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

const onAutoFillStart = keyframes`
  from {
    /** autofill start - this comment is needed so styled-components creates a unique instance of this */
  }
  to {
  }
`;
const onAutoFillCancel = keyframes`
  from {
    /** autofill cancel - this comment is needed so styled-components creates a unique instance of this */
  }
  to {
  }
`;

/**
 * Autofill css that needs to be added to the native input element to detect the
 * autofill animation.
 */
export const autofillCss: FlattenSimpleInterpolation = css`
  &:-webkit-autofill,
  &:-webkit-autofill:hover,
  &:-webkit-autofill:focus {
    -webkit-text-fill-color: ${Colors.Text.Primary.Default};
    // removes the default browser styled background box
    -webkit-background-clip: text;
  }

  &:-webkit-autofill {
    // Expose a hook for JavaScript when auto fill is shown.
    // JavaScript can capture 'animationstart' events
    animation-name: ${onAutoFillStart};
    animation-duration: 0.001s; // fix for triggering the autofill everytime: https://stackoverflow.com/questions/11708092/detecting-browser-autofill#comment125261577_41530164
  }

  &:not(:-webkit-autofill) {
    // Expose a hook for JS onAutoFillCancel
    // JavaScript can capture 'animationstart' events
    animation-name: ${onAutoFillCancel};
    animation-duration: 0.001s; // fix for triggering the autofill everytime: https://stackoverflow.com/questions/11708092/detecting-browser-autofill#comment125261577_41530164
  }
`;

/**
 * useAutofillEvent hook returns the animationHandler that needs to be bound on the
 * native element to detect if it is autofilling and returns that state.
 */
export function useAutofillEvent() {
  const [isAutoFilled, setIsAutoFilled] = useState<boolean>(false);

  const onAnimationStart = (e: React.AnimationEvent<HTMLElement>) => {
    switch (e.animationName) {
      case onAutoFillStart.getName():
        setIsAutoFilled(true);
        break;
      case onAutoFillCancel.getName():
        setIsAutoFilled(false);
        break;
    }
  };

  return { isAutoFilled, onAnimationStart };
}
